const songs = [
  {
  title: "Munbe Vaa",
  artist: "A.R. Rahman & Shreya Ghoshal",
  cover: "data:image/jpeg;base64,", // Replace with actual cover if needed
  src:"https://archive.org/download/AskkuLaska/Munbe%20Vaa.mp3"

},
 {
  title: "Appadi Podu",
  artist: "Vijay & Anuradha Sriram",
  cover: "data:image/jpeg;base64,", 
  src: "https://archive.org/download/VijayHits/Appadi%20Podu.mp3"
},
{
  title: "Aathi",
  artist: "Vijay & Anirudh Ravichander",
  cover: "data:image/jpeg;base64,",
  src: "https://archive.org/download/AskkuLaska/Aathi.mp3"
},
{
  title: "Adada Mazhaida",
  artist: "Hariharan & Chinmayi (Music: Harris Jayaraj)",
  cover: "data:image/jpeg;base64,",
  src: "https://archive.org/download/tamildancesongs/Adada%20Mazhaida.mp3"
},
];

const audio = document.getElementById("audio");
const cover = document.getElementById("cover");
const title = document.getElementById("title");
const artist = document.getElementById("artist");
const playBtn = document.getElementById("play");
const prevBtn = document.getElementById("prev");
const nextBtn = document.getElementById("next");
const repeatBtn = document.getElementById("repeat");
const muteBtn = document.getElementById("mute");
const volumeSlider = document.getElementById("volume-slider");
const currentTimeEl = document.getElementById("current-time");
const durationEl = document.getElementById("duration");
const progressBarBg = document.getElementById("progress-bar-bg");
const progressBar = document.getElementById("progress-bar");
const playlistEl = document.getElementById("playlist");

let songIndex = 0;
let isPlaying = false;
let isRepeat = false;

function loadSong(song) {
  title.textContent = song.title;
  artist.textContent = song.artist;
  cover.src = song.cover;
  audio.src = song.src;
}

function playSong() {
  audio.play();
  isPlaying = true;
  playBtn.innerHTML = "<span>&#10074;&#10074;</span>";
}

function pauseSong() {
  audio.pause();
  isPlaying = false;
  playBtn.innerHTML = "<span>&#9654;</span>";
}

playBtn.addEventListener("click", () => {
  isPlaying ? pauseSong() : playSong();
});

function nextSong() {
  songIndex = (songIndex + 1) % songs.length;
  loadSong(songs[songIndex]);
  playSong();
}

function prevSong() {
  songIndex = (songIndex - 1 + songs.length) % songs.length;
  loadSong(songs[songIndex]);
  playSong();
}

nextBtn.addEventListener("click", nextSong);
prevBtn.addEventListener("click", prevSong);

repeatBtn.addEventListener("click", () => {
  isRepeat = !isRepeat;
  repeatBtn.style.color = isRepeat ? "green" : "black";
});

audio.addEventListener("timeupdate", () => {
  if (audio.duration) {
    const progressPercent = (audio.currentTime / audio.duration) * 100;
    progressBar.style.width = `${progressPercent}%`;
    currentTimeEl.textContent = formatTime(audio.currentTime);
    durationEl.textContent = formatTime(audio.duration);
  }
});

progressBarBg.addEventListener("click", (e) => {
  const width = progressBarBg.clientWidth;
  const clickX = e.offsetX;
  const duration = audio.duration;
  audio.currentTime = (clickX / width) * duration;
});

volumeSlider.addEventListener("input", (e) => {
  audio.volume = e.target.value;
});

muteBtn.addEventListener("click", () => {
  audio.muted = !audio.muted;
  muteBtn.innerHTML = audio.muted ? "<span>&#128263;</span>" : "<span>&#128266;</span>";
});

audio.addEventListener("ended", () => {
  if (isRepeat) {
    playSong();
  } else {
    nextSong();
  }
});

function formatTime(sec) {
  const minutes = Math.floor(sec / 60);
  const seconds = Math.floor(sec % 60).toString().padStart(2, "0");
  return `${minutes}:${seconds}`;
}

songs.forEach((song, index) => {
  const li = document.createElement("li");
  li.textContent = `${song.title} - ${song.artist}`;
  li.addEventListener("click", () => {
    songIndex = index;
    loadSong(song);
    playSong();
  });
  playlistEl.appendChild(li);
});

loadSong(songs[songIndex]);
